INSERT INTO `proverbs___proverbs_location_recognition` (`COL 1`, `COL 2`, `COL 3`, `COL 4`, `COL 5`, `COL 6`, `COL 7`, `COL 8`, `COL 9`) VALUES
('Term', 'Meaning_of_term', 'Dialect type', 'Location_Recognition_question', 'Cultural_Interpretation_question', 'Contextual_Usage_question', 'Fill_in_Blank_question', 'True_False_question', 'Meaning_question'),
('أَدْنَى حَمُول غَانا راعِيه', '(عند أهل السراة) تستخدم بمعنى أن الأنسان يعيش على أدنى الميسور والموجود. وهي تفيد القناعة. أدنى: أقل. حمول: ما يحمل على الجمل وهي هنا ما تقتنيه. غانا: لغة في أغنى. راعيه: صاحبه.', 'Southern', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: في أي منطقة سعودية يستخدم هذا المثل \"أدْنَى حَمُول غَانا راعِيه\" بشكل شائع؟\nالخيارات:\nأ) نجد\nب) الحجاز\nج) عسير\nد) المنطقة الشرقية\nالإجابة الصحيحة: ج', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ما الدلالة الثقافية للمثل \"أدْنَى حَمُول غَانا راعِيه\"؟\nالخيارات:\nA) القناعة والرضا تجعل الإنسان غنيًا\nB) الطموح العالي هو السبيل الوحيد للنجاح\nC) كثرة المال تضمن السعادة والاستقرار\nD) التنقل والترحال يساعدان في تحقيق الثروة\nالإجابة الصحيحة: A) القناعة والرضا تجعل الإنسان غنيًا', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: أي من المواقف التالية يناسب استخدام المثل \"أدْنَى حَمُول غَانا راعِيه\"؟\nالخيارات:\nA) شخص يعيش حياة بسيطة وراضٍ بما لديه\nB) تاجر يضاعف استثماراته بحثًا عن الثراء\nC) موظف يرفض العمل لأنه لا يناسب طموحه الكبير\nD) مسافر يزور عدة دول بحثًا عن فرص جديدة\nالإجابة الصحيحة: A) شخص يعيش حياة بسيطة وراضٍ بما لديه', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: يُقال المثل \"أدْنَى حَمُول غَانا راعِيه\" لمن _______ بالقليل ولم يسعَ إلى المزيد.\nالخيارات:\nA) رضي\nB) طمع\nC) خسر\nD) بالغ\nالإجابة الصحيحة: A) رضي', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: يدل المثل \"أدْنَى حَمُول غَانا راعِيه\" على أن الطمع والجشع يؤديان إلى الفقر.\nالخيارات:\nA) صح\nB) خطأ\nالإجابة الصحيحة: B) خطأ', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ما الفكرة الأساسية التي يعبر عنها المثل \"أدْنَى حَمُول غَانا راعِيه\"؟\nالخيارات:\nA) القناعة بما هو متاح وعدم الطمع\nB) أهمية جمع المال وعدم الإسراف\nC) الكرم والسخاء مع الآخرين\nD) السفر والتنقل بحثًا عن الرزق\nالإجابة الصحيحة: A) القناعة بما هو متاح وعدم الطمع'),
('أن كان مالك من ذراعك نجده شربك على يدين الرجال هماج', 'هي بالأساس بيت قصيد، لكن أُستخدم كمثل ومعناها أنك ستتعرض للمذلة، أن لم تعتمد على نفسك', 'Central', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: في أي منطقة سعودية يستخدم هذا المثل بشكل شائع؟\nالخيارات:\nأ) نجد\nب) الحجاز\nج) عسير\nد) المنطقة الشرقية\nالإجابة الصحيحة: أ', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ما الدلالة الثقافية للمثل \"إن كان مالك من ذراعك نجده، شربك على يدين الرجال هماج\"؟\nالخيارات:\nA) العمل الجاد والاعتماد على النفس هما مفتاح النجاح\nB) التعاون مع الآخرين أفضل من العمل الفردي\nC) كثرة المال تضمن السعادة والاستقرار\nD) الرزق يأتي دون الحاجة إلى جهد\nالإجابة الصحيحة: A) العمل الجاد والاعتماد على النفس هما مفتاح النجاح', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: أي من المواقف التالية يناسب استخدام المثل \"إن كان مالك من ذراعك نجده، شربك على يدين الرجال هماج\"؟\nالخيارات:\nA) شخص يعمل بجد ويبني مستقبله بنفسه\nB) رجل يعتمد على المساعدات من الآخرين دون جهد\nC) طالب يبحث عن أسهل الطرق للنجاح دون دراسة\nD) شخص يفضل الاعتماد على دعم عائلته بدلاً من العمل\nالإجابة الصحيحة: A) شخص يعمل بجد ويبني مستقبله بنفسه', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: يُقال المثل \"إن كان مالك من ذراعك نجده، شربك على يدين الرجال هماج\" لمن _______ على نفسه في كسب رزقه.\nالخيارات:\nA) اعتمد\nB) أهمل\nC) تردد\nD) رفض\nالإجابة الصحيحة: A) اعتمد', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: يشير المثل \"إن كان مالك من ذراعك نجده، شربك على يدين الرجال هماج\" إلى أهمية الاتكال على الآخرين في تحقيق النجاح.\nالخيارات:\nA) صح\nB) خطأ\nالإجابة الصحيحة: B) خطأ', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ما الفكرة الأساسية التي يعبر عنها المثل \"إن كان مالك من ذراعك نجده، شربك على يدين الرجال هماج\"؟\nالخيارات:\nA) الاعتماد على النفس هو السبيل لتحقيق النجاح\nB) الكرم والتعاون مع الآخرين أمر ضروري\nC) العمل الجماعي أكثر فائدة من العمل الفردي\nD) القناعة والرضا هما أهم أسباب السعادة\nالإجابة الصحيحة: A) الاعتماد على النفس هو السبيل لتحقيق النجاح'),
('إذا حجت البقرة على قرونها', 'بمعنى المستحيل ولايمكن وقوعة', 'General', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: في أي دولة يتم استخدام هذا المثل بشكل شائع؟\nالخيارات:\nأ) البحرين\nب) الكويت\nج) الإمارات\nد)السعودية\nالإجابة الصحيحة: د', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ما الدلالة الثقافية للمثل \"إذا حجت البقرة على قرونها\"؟\nالخيارات:\nA) التأكيد على إمكانية تحقيق الأمور الصعبة\nB) رفض فكرة حدوث أمر مستحيل\nC) تقدير الجهود المبذولة لتحقيق الهدف\nD) تشجيع الآخرين على التفكير في المستحيل\nالإجابة الصحيحة: B) رفض فكرة حدوث أمر مستحيل', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: في أي من المواقف التالية يمكن استخدام المثل \"إذا حجت البقرة على قرونها\"؟\nالخيارات:\nA) عندما يعد شخص ما بشيء مستحيل أو صعب جدًا تحقيقه\nB) عندما يتحدث شخص عن نجاحات غير محتملة\nC) عندما يتم الإعلان عن أمر مهم في المستقبل\nD) عندما تتحدث عن وضع طبيعي ومحتمل\nالإجابة الصحيحة: A) عندما يعد شخص ما بشيء مستحيل أو صعب جدًا تحقيقه', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: المثل \"إذا حجت البقرة على قرونها\" يعبر عن _______ شيء غير ممكن أو مستحيل.\nالخيارات:\nA) إمكانية\nB) استحالة\nC) فرصة\nD) توقع\nالإجابة الصحيحة: B) استحالة', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: يشير المثل \"إذا حجت البقرة على قرونها\" إلى شيء مستحيل أو غير قابل للتحقيق.\nالخيارات:\nA) صح\nB) خطأ\nالإجابة الصحيحة: A) صح', 'المهمة: اختر إجابة واحدة فقط دون أي ملاحظات إضافية.\nالسؤال: ماذا يعني المثل \"إذا حجت البقرة على قرونها\"؟\nالخيارات:\nA) شيء يمكن تحقيقه إذا تمت الظروف بشكل جيد\nB) شيء مستحيل أو غير قابل للتحقيق\nC) شيء يحدث في حالة نادرة\nD) شيء يجب أن يتم في الوقت المحدد\nالإجابة الصحيحة: B) شيء مستحيل أو غير قابل للتحقيق'),
('إلي يجيك أحسن من إلي ترحلو', 'مثل معناه: إلي يفكر فيك أحسن من إلي تفكر فيه.', 'Western', 'المهمة: حدد الموقع الذي يُستخدم فيه هذا المثل.\nالسؤال: في أي منطقة سعودية يُستخدم المثل \'إلي يجيك أحسن من إلي ترحلو\' بشكل أكثر شيوعاً؟\nالخيارات:\nأ) الرياض\nب) مكة\nج) الدمام\nد) جدة\nالإجابة الصحيحة: د', 'المهمة: وضح المعنى الثقافي للمثل.\nالسؤال: ماذا يعني المثل \'إلي يجيك أحسن من إلي ترحلو\' في الثقافة السعودية؟\nالخيارات:\nأ) يفضل الناس من يزورهم على من يهجرهم\nب) تستمر العلاقات عبر المراسلة\nج) الصداقة ليست مهمة\nد) الزيارة ليست ذات قيمة\nالإجابة الصحيحة: أ', 'المهمة: اختر الجملة التي تناسب استخدام المثل.\nالسؤال: في أي موقف يمكن القول \'إلي يجيك أحسن من إلي ترحلو\'؟\nالخيارات:\nأ) عندما تفكر في الذهاب لزيارة شخص\nب) عند التحدث عن شخص لم يعد مهتمًا بك\nج) عند استضافتك لصديق قادم من سفر\nد) عند توديع شخص مقرب\nالإجابة الصحيحة: ج', 'المهمة: أكمل الفراغ بما يناسب.\nالسؤال: المثل \'إلي يجيك أحسن من إلي ترحلو\' يدل على أن __________.\nالخيارات:\nأ) الشخص الذي يهتم بك أفضل\nب) الهجر أفضل من الزيارة\nج) الرحيل أفضل من الزيارة\nد) التفكير هو المهم\nالإجابة الصحيحة: أ', 'المهمة: حدد ما إذا كانت العبارة صحيحة أو خاطئة.\nالسؤال: المثل \'إلي يجيك أحسن من إلي ترحلو\' يعني أن الشخص الذي يهتم بك أفضل ممن تتركه.\nالخيارات:\nأ) صحيح\nب) خاطئ\nالإجابة الصحيحة: أ', 'المهمة: اذكر معنى المثل التالي.\nالسؤال: ما معنى المثل \'إلي يجيك أحسن من إلي ترحلو\'؟\nالخيارات:\nأ) إلي سيفكر فيك أحسن من إلي ترحل له\nب) إلي تحبه أكثر من إلي يحبك\nج) إلي يزورك أفضل من إلي تتركه\nد) إلي يتكلم عنك أفضل من إلي تتكلم عنه\nالإجابة الصحيحة: أ'),
('ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه', 'وصَلْمَعةُ‎ ‎بن‎ قَلْمَعةَ: كناية عمن لا يعرف ولا يُعْرَفُ أَبوه وهذا المثل يقال عند ذم الشخص', 'Central', 'المهمة: حدد الموقع الأكثر شيوعاً لاستخدام هذا المثل.\nالسؤال: أين يُستخدم مثل \'ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه\' بشكل أكبر؟\nالخيارات:\nأ) الرياض\nب) جدة\nج) الدمام\nد) المنطقة الشرقية\nالإجابة الصحيحة: أ', 'المهمة: فسر المعنى الثقافي لمثل \'ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه\'.\nالسؤال: لماذا يُعتبر هذا المثل مهمًا في الثقافة السعودية؟\nالخيارات:\nأ) لأنه يدعو إلى التعلم والمثابرة\nب) لأنه ينبه لعدم الاعتماد على بعض الأشخاص\nج) لأنه يعترف بقدرات الآخرين\nد) لأنه يعزز التواصل الاجتماعي\nالإجابة الصحيحة: ب', 'المهمة: ما هو السياق المناسب لاستخدام مثل \'ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه\'?\nالسؤال: عندما تريد الإشارة لشخص عديم الفائدة، أي من الخيارات التالية هو السياق الصحيح لاستخدام المثل؟\nالخيارات:\nأ) أثناء مدح الأصدقاء\nب) عند التحدث عن شخص يتمتع بذكاء عالٍ\nج) في حالة محاولة إقناع شخص عنيد\nد) عند مناقشة النجاح والإنجازات\nالإجابة الصحيحة: ج', 'المهمة: أكمل الفراغ في الجملة.\nالسؤال: يستخدم المثل \'ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه\' للحديث عن __________.\nالخيارات:\nأ) القوة والشجاعة\nب) الغباء والعناد\nج) الفخر والاعتزاز\nد) القيم والمبادئ\nالإجابة الصحيحة: ب', 'المهمة: حدد ما إذا كانت العبارة صحيحة أم خاطئة.\nالسؤال: المثل \'ابن صلمعه بن قلمعه\' يُستخدم لمدح الأشخاص.\nالخيارات:\nأ) صحيح\nب) خطأ\nالإجابة الصحيحة: ب', 'المهمة: حدد المعنى الحقيقي للمثل المدخل.\nالسؤال: ما المقصود بمثل \'ابن صلمعه بن قلمعه ما تنفع معاه الحيل المجمعه\'؟\nالخيارات:\nأ) يشير إلى شخص يعرف والديه جيدًا\nب) يعني عدم جدوى الحيل مع شخص عديم القيم\nج) يدل على شخص لديه مهارات عديدة\nد) يعني شخص مشهور في عائلته\nالإجابة الصحيحة: ب'),
('ابو فرفور ذنبو مغفور', 'اللي نحبه نغفرله كل شي', 'Western', 'المهمة: حدد الموقع الذي يرتبط به استخدام العبارة.\nالسؤال: في أي منطقة سعودية تُستخدم عبارة \'ابو فرفور ذنبو مغفور\' بشكل شائع؟\nالخيارات:\nأ) جدة\nب) الرياض\nج) الدمام\nد) مكة\nالإجابة الصحيحة: أ', 'المهمة: اشرح ما تعكسه هذه العبارة عن الثقافة السعودية.\nالسؤال: ماذا تعكس عبارة \'ابو فرفور ذنبو مغفور\' عن العادات الاجتماعية في المجتمع السعودي؟\nالخيارات:\nأ) التشدد في العقوبات\nب) التسامح والمودة بين الأفراد\nج) أهمية القانون\nد) دعم النجاح الفردي\nالإجابة الصحيحة: ب', 'المهمة: اختر الجملة التي يمكن أن تستخدم فيها العبارة.\nالسؤال: متى يمكن أن نستخدم عبارة \'ابو فرفور ذنبو مغفور\'؟\nالخيارات:\nأ) عندما نتحدث عن تطبيق القانون\nب) عند الحديث عن شخص عزيز أخطأ\nج) عندما نناقش فائدة الخطأ\nد) عند الحديث عن العدالة\nالإجابة الصحيحة: ب', 'المهمة: أكمل الجملة بما يناسب العبارة.\nالسؤال: تُستخدم عبارة \'ابو فرفور ذنبو مغفور\' للدلالة على أن _____.\nالخيارات:\nأ) الأخطاء مبررة للناس المقربين\nب) العقوبة ضرورية للجميع\nج) الحب لا يغفر الأخطاء\nد) الفشل نهاية الطريق\nالإجابة الصحيحة: أ', 'المهمة: حدد ما إذا كانت العبارة صحيحة أم خاطئة.\nالسؤال: العبارة \'ابو فرفور ذنبو مغفور\' تعني أن الشخص لن يُعاقب على أخطائه.\nالخيارات:\nأ) صحيح\nب) خاطئ\nالإجابة الصحيحة: أ', 'المهمة: حدد المعنى الصحيح للعبارة \'ابو فرفور ذنبو مغفور\'.\nالسؤال: ما المقصود بعبارة \'ابو فرفور ذنبو مغفور\'؟\nالخيارات:\nأ) الشخص الذي يخطئ يعاقب\nب) اللي نحبه نغفرله كل شي\nج) كل واحد له ذنوبه\nد) الخطأ مصيره الفشل\nالإجابة الصحيحة: ب'),
